    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collClSolicitudPrestamos) {
                foreach ($this->collClSolicitudPrestamos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collClTransferencias) {
                foreach ($this->collClTransferencias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collClUsuarios) {
                foreach ($this->collClUsuarios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collClienteContenidos) {
                foreach ($this->collClienteContenidos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aFrecConsultaCliente instanceof Persistent) {
              $this->aFrecConsultaCliente->clearAllReferences($deep);
            }
            if ($this->aClienteEstado instanceof Persistent) {
              $this->aClienteEstado->clearAllReferences($deep);
            }
            if ($this->aUnidconservadora instanceof Persistent) {
              $this->aUnidconservadora->clearAllReferences($deep);
            }
            if ($this->aSoporteCliente instanceof Persistent) {
              $this->aSoporteCliente->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collClSolicitudPrestamos instanceof PropelCollection) {
            $this->collClSolicitudPrestamos->clearIterator();
        }
        $this->collClSolicitudPrestamos = null;
        if ($this->collClTransferencias instanceof PropelCollection) {
            $this->collClTransferencias->clearIterator();
        }
        $this->collClTransferencias = null;
        if ($this->collClUsuarios instanceof PropelCollection) {
            $this->collClUsuarios->clearIterator();
        }
        $this->collClUsuarios = null;
        if ($this->collClienteContenidos instanceof PropelCollection) {
            $this->collClienteContenidos->clearIterator();
        }
        $this->collClienteContenidos = null;
        $this->aFrecConsultaCliente = null;
        $this->aClienteEstado = null;
        $this->aUnidconservadora = null;
        $this->aSoporteCliente = null;
    }

